    traits: ['bromista', 'fanfarron', 'supersticioso'], likes: ['tabaco', 'vino', 'pulpo', 'concha'], dislikes: ['agua_bendita'],
    hello: ['¡Ah del barco! ¿Qué te pongo, grumete?', '¿Te conté cuando me tragó una ballena en Menorca? ¿No? Siéntate.', '¡Mi tripulación favorita! Esta ronda la paga el mar.'],
