    traits: ['gritona', 'generosa', 'tolerante'], likes: ['concha', 'sardina', 'cinta', 'vino'], dislikes: ['perfume'],
    hello: ['¡Sardinas vivas, que saltan solas a la sartén! ¿Qué te pongo, rey?', '¡Guapo, hoy te guardé la dorada más bonita del mar!', '¡Tú aquí siempre tienes tu pescadito, y sin pagar!'],
