    traits: ['astuto', 'amable', 'avaro'], likes: ['plata', 'anillo', 'perfume', 'tinta_sepia'], dislikes: ['barretina'],
    hello: ['¡Amico! Mercancía de Génova, de Alejandría, de Constantinopla. ¡Mira, mira!', 'Para ti, precio de amigo. Bueno, de conocido.', '¡Mi socio favorito de Barcanueva! Tengo algo que no enseño a nadie.'],
