    traits: ['seductor', 'tolerante', 'antiguo'], likes: ['anillo', 'lib_tibidabo', 'vino'], dislikes: ['agua_bendita', 'cera', 'habito'],
    hello: ['Mira abajo. Todo eso: la ciudad, el mar, el llano. Bonito, ¿verdad?', 'Vuelves. Siempre vuelven.', 'Somos viejos amigos ya. Pide.'],
